param()

$ErrorActionPreference = "Stop"
$utf8NoBom = [System.Text.UTF8Encoding]::new($false)

$priorityLangs = @('fr','es','de','pt')
$articleNames = @('article-19.html','article-20.html','article-21.html','article-22.html')

$rows = New-Object "System.Collections.Generic.List[object]"

function Add-Row {
    param(
        [Parameter(Mandatory = $true)][string]$en,
        [Parameter(Mandatory = $true)][string]$fr,
        [Parameter(Mandatory = $true)][string]$es,
        [Parameter(Mandatory = $true)][string]$de,
        [Parameter(Mandatory = $true)][string]$pt
    )

    $script:rows.Add([pscustomobject]@{
        en = $en
        fr = $fr
        es = $es
        de = $de
        pt = $pt
    }) | Out-Null
}

function Apply-LocaleRows {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$Lang
    )

    foreach ($row in ($rows | Sort-Object { $_.en.Length } -Descending)) {
        $replacement = $row.$Lang
        if ([string]::IsNullOrWhiteSpace($replacement)) { continue }
        $Content = $Content.Replace($row.en, $replacement)
    }

    return $Content
}

function Set-FirstRegex {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$Pattern,
        [Parameter(Mandatory = $true)][string]$Replacement
    )

    return [regex]::Replace($Content, $Pattern, $Replacement, 1)
}

