 $sourceGamePath = Join-Path $PSScriptRoot "game-mode-subtitles.html"
if (-not (Test-Path $sourceGamePath)) {
    throw "Missing source page: $sourceGamePath"
}
$sourceGameContent = [System.IO.File]::ReadAllText($sourceGamePath, $utf8NoBom)

foreach ($lang in $priorityLangs) {
    $langDir = Join-Path $PSScriptRoot $lang
    if (-not (Test-Path $langDir)) {
        New-Item -Path $langDir -ItemType Directory | Out-Null
    }
    $gamePath = Join-Path $langDir "game-mode-subtitles.html"

    $content = $sourceGameContent
    $seo = $gameSeo[$lang]
    $url = "https://live-subtitles.com/$lang/game-mode-subtitles.html"

    $content = Set-FirstRegex -Content $content -Pattern '<html lang="[^"]+">' -Replacement "<html lang=`"$lang`">"
    $content = Set-FirstRegex -Content $content -Pattern '<title>.*</title>' -Replacement "<title>$($seo.title)</title>"
    $content = Set-FirstRegex -Content $content -Pattern '<meta name="description" content="[^"]*">' -Replacement "<meta name=`"description`" content=`"$($seo.description)`">"
    $content = Set-FirstRegex -Content $content -Pattern '<meta name="keywords" content="[^"]*">' -Replacement "<meta name=`"keywords`" content=`"$($seo.keywords)`">"
    $content = Set-FirstRegex -Content $content -Pattern '<meta name="robots" content="[^"]+">' -Replacement '<meta name="robots" content="index, follow">'
    $content = Set-FirstRegex -Content $content -Pattern '<link rel="canonical" href="[^"]+" />' -Replacement "<link rel=`"canonical`" href=`"$url`" />"
    $content = Set-FirstRegex -Content $content -Pattern '<meta property="og:title" content="[^"]*">' -Replacement "<meta property=`"og:title`" content=`"$($seo.title)`">"
    $content = Set-FirstRegex -Content $content -Pattern '<meta property="og:description" content="[^"]*">' -Replacement "<meta property=`"og:description`" content=`"$($seo.ogDescription)`">"
    $content = Set-FirstRegex -Content $content -Pattern '<meta property="og:url" content="[^"]+">' -Replacement "<meta property=`"og:url`" content=`"$url`">"
    $content = Set-FirstRegex -Content $content -Pattern '<meta name="twitter:title" content="[^"]*">' -Replacement "<meta name=`"twitter:title`" content=`"$($seo.title)`">"
    $content = Set-FirstRegex -Content $content -Pattern '<meta name="twitter:description" content="[^"]*">' -Replacement "<meta name=`"twitter:description`" content=`"$($seo.twitterDescription)`">"

    $content = $content.Replace('href="/"', "href=`"/$lang/`"")
    $content = $content.Replace('href="discord-twitch-subtitles.html"', "href=`"/$lang/discord-twitch-subtitles.html`"")
    $content = $content.Replace('href="/articles/en/article-19.html"', "href=`"/articles/$lang/article-19.html`"")
    $content = $content.Replace('href="/articles/en/article-20.html"', "href=`"/articles/$lang/article-20.html`"")
    $content = $content.Replace('href="/articles/en/article-21.html"', "href=`"/articles/$lang/article-21.html`"")
    $content = $content.Replace('href="/articles/en/article-22.html"', "href=`"/articles/$lang/article-22.html`"")

    $content = Apply-LocaleRows -Content $content -Lang $lang
    [System.IO.File]::WriteAllText($gamePath, $content, $utf8NoBom)
}

foreach ($lang in $priorityLangs) {
    $articlesDir = Join-Path $PSScriptRoot "articles\$lang"
    if (-not (Test-Path $articlesDir)) {
        New-Item -Path $articlesDir -ItemType Directory | Out-Null
    }

    foreach ($articleName in $articleNames) {
        $sourcePath = Join-Path $PSScriptRoot "articles\en\$articleName"
        if (-not (Test-Path $sourcePath)) {
            throw "Missing source article: $sourcePath"
        }

        $path = Join-Path $articlesDir $articleName
        $content = [System.IO.File]::ReadAllText($sourcePath, $utf8NoBom)
        $url = "https://live-subtitles.com/articles/$lang/$articleName"

        $content = Set-FirstRegex -Content $content -Pattern '<html lang="[^"]+">' -Replacement "<html lang=`"$lang`">"
        $content = Set-FirstRegex -Content $content -Pattern '<meta name="robots" content="[^"]+">' -Replacement '<meta name="robots" content="index, follow">'
        $content = Set-FirstRegex -Content $content -Pattern '<link rel="canonical" href="[^"]+" />' -Replacement "<link rel=`"canonical`" href=`"$url`" />"
        $content = Set-FirstRegex -Content $content -Pattern '<meta property="og:url" content="[^"]+">' -Replacement "<meta property=`"og:url`" content=`"$url`">"
        $content = Set-FirstRegex -Content $content -Pattern '"mainEntityOfPage": "[^"]+"' -Replacement "`"mainEntityOfPage`": `"$url`""

        $content = $content.Replace('href="/game-mode-subtitles.html"', "href=`"/$lang/game-mode-subtitles.html`"")
        $content = $content.Replace('href="/discord-twitch-subtitles.html"', "href=`"/$lang/discord-twitch-subtitles.html`"")

        $content = Apply-LocaleRows -Content $content -Lang $lang
        [System.IO.File]::WriteAllText($path, $content, $utf8NoBom)
    }
}

Write-Host "Localized priority game cluster (fr/es/de/pt): indexability + core body translation + self-canonical."
